import os
from typing import Any

import boto3
from google.cloud import secretmanager
from azure.keyvault.secrets import SecretClient
from azure.identity import DefaultAzureCredential

def get_aws_secrets_manager_client() -> Any:
    return boto3.client("secretsmanager", region_name=os.environ.get("AWS_REGION", "us-east-1"))

def get_google_secret_manager_client() -> secretmanager.SecretManagerServiceClient:
    return secretmanager.SecretManagerServiceClient()

def get_azure_key_vault_secret_client(vault_url: str) -> SecretClient:
    credential = DefaultAzureCredential()
    return SecretClient(vault_url=vault_url, credential=credential)

import os
import json
from typing import Optional

from security_client import get_aws_secrets_manager_client
from security_models import Secret

def fetch_api_key(secret_name: str) -> Optional[Secret]:
    client = get_aws_secrets_manager_client()
    try:
        get_secret_value_response = client.get_secret_value(SecretId=secret_name)
        if 'SecretString' in get_secret_value_response:
            secret_value = get_secret_value_response['SecretString']
            return Secret(name=secret_name, value=secret_value, arn=get_secret_value_response.get('ARN'))
        elif 'SecretBinary' in get_secret_value_response:
            # Handle binary secrets if necessary
            return Secret(name=secret_name, value=None, arn=get_secret_value_response.get('ARN'), metadata={"binary": True})
    except client.exceptions.ResourceNotFoundException:
        print(f"Secret '{secret_name}' not found.")
    except Exception as e:
        print(f"Error fetching secret '{secret_name}': {e}")
    return None

if __name__ == '__main__':
    # Example usage (requires AWS_REGION and secret to exist)
    # For demonstration, assume secret 'my_api_key' exists in AWS Secrets Manager
    # and contains a plain string API key.
    # Set AWS_REGION environment variable or configure boto3 credentials.
    api_key_secret = fetch_api_key(os.environ.get("API_KEY_SECRET_NAME", "my_api_key"))
    if api_key_secret and api_key_secret.value:
        print(f"Fetched API Key (first 5 chars): {api_key_secret.value[:5]}...")
    else:
        print("Failed to fetch API Key.")

import os
import json
from typing import Optional

from google.cloud.secretmanager_v1 import SecretManagerServiceClient
from security_client import get_google_secret_manager_client
from security_models import Secret

def fetch_db_secret(project_id: str, secret_id: str, version_id: str = "latest") -> Optional[Secret]:
    client: SecretManagerServiceClient = get_google_secret_manager_client()
    name = f"projects/{project_id}/secrets/{secret_id}/versions/{version_id}"
    try:
        response = client.access_secret_version(name=name)
        payload = response.payload.data.decode("UTF-8")
        return Secret(name=secret_id, value=payload, version_id=response.name)
    except Exception as e:
        print(f"Error fetching database secret '{secret_id}': {e}")
    return None

if __name__ == '__main__':
    # Example usage (requires GOOGLE_CLOUD_PROJECT environment variable)
    # For demonstration, assume a secret 'my-db-secret' exists in Google Secret Manager
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        print("Please set the GOOGLE_CLOUD_PROJECT environment variable.")
    else:
        db_secret = fetch_db_secret(project_id, os.environ.get("DB_SECRET_ID", "my-db-secret"))
        if db_secret and db_secret.value:
            print(f"Fetched DB Secret (first 5 chars): {db_secret.value[:5]}...")
        else:
            print("Failed to fetch DB Secret.")

import os
import json
from typing import Any, Dict, Optional

from azure.keyvault.secrets import SecretClient
from security_client import get_azure_key_vault_secret_client
from security_models import Secret

def parse_json_secret(vault_url: str, secret_name: str) -> Optional[Dict[str, Any]]:
    client: SecretClient = get_azure_key_vault_secret_client(vault_url)
    try:
        key_vault_secret = client.get_secret(secret_name)
        if key_vault_secret.value:
            return json.loads(key_vault_secret.value)
    except Exception as e:
        print(f"Error fetching or parsing JSON secret '{secret_name}' from Azure Key Vault: {e}")
    return None

if __name__ == '__main__':
    # Example usage (requires AZURE_VAULT_URL and appropriate Azure credentials)
    # For demonstration, assume a secret 'my-json-config' exists in Azure Key Vault
    # and contains a JSON string, e.g., '{"key":"value"}'.
    vault_url = os.environ.get("AZURE_VAULT_URL")
    if not vault_url:
        print("Please set the AZURE_VAULT_URL environment variable.")
    else:
        json_secret_content = parse_json_secret(vault_url, os.environ.get("JSON_SECRET_NAME", "my-json-config"))
        if json_secret_content:
            print(f"Fetched and parsed JSON Secret: {json.dumps(json_secret_content, indent=2)}")
        else:
            print("Failed to fetch or parse JSON Secret.")

import os
from typing import Dict, Any

from openai import OpenAI

def check_text_safety(text: str) -> Dict[str, Any]:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    try:
        response = client.moderations.create(input=text)
        # The moderation API returns a list of results, we'll take the first one.
        # Accessing response.results[0] directly as per OpenAI library usage.
        return response.results[0].model_dump()
    except Exception as e:
        print(f"Error checking text safety with OpenAI: {e}")
        return {"error": str(e)}

def check_secret_label_safety(secret_name: str, labels: Dict[str, str], notes: str) -> Dict[str, Any]:
    combined_text = f"Secret Name: {secret_name}\nLabels: {labels}\nNotes: {notes}"
    print(f"Checking safety for: {combined_text[:100]}...")
    return check_text_safety(combined_text)

if __name__ == '__main__':
    # Example usage (requires OPENAI_API_KEY environment variable)
    # Example 1: Safe content
    safe_secret_name = "api_key_prod_us"
    safe_labels = {"environment": "production", "owner": "team-a"}
    safe_notes = "API key for production environment. Rotated monthly."
    safety_report_safe = check_secret_label_safety(safe_secret_name, safe_labels, safe_notes)
    print(f"\nSafety report for safe content:\n{safety_report_safe}")

    # Example 2: Potentially unsafe content
    unsafe_secret_name = "bad_secret_test"
    unsafe_labels = {"risk": "high", "leak": "public"}
    unsafe_notes = "This secret was found in a public repository and contains sensitive information. It needs immediate rotation."
    safety_report_unsafe = check_secret_label_safety(unsafe_secret_name, unsafe_labels, unsafe_notes)
    print(f"\nSafety report for unsafe content:\n{safety_report_unsafe}")
